#!/usr/bin/env bash
# Verify a TPC-DI staging area generated by DIGen.
#
#   bash scripts/verify-phase-02.sh                     scale factor 5
#   bash scripts/verify-phase-02.sh tpcdi-staging-sf3   any generated volume
#
# Read-only.  Every check runs inside a container against the volume, so no
# result depends on the host having any particular tool.  Exits non-zero if
# any check fails.
set -u
VOL="${1:-tpcdi-staging-sf5}"

# The scale factor comes from the volume name, and the data lives at sf<N>
# inside it.  Hard-coding sf5 made this report 14 false failures against a
# perfectly good SF=3 volume.
case "$VOL" in
  *-sf[0-9]*) SF="${VOL##*-sf}";;
  *) echo "cannot tell the scale factor from '$VOL'." >&2
     echo "expected a name ending in -sf<N>, e.g. tpcdi-staging-sf5" >&2; exit 2;;
esac
DIR="/staging/sf${SF}"

# Counts measured at the scale factors we have generated.  Other scale factors
# are checked for internal consistency instead of against a literal.
case "$SF" in
  5) WANT="7804509 33380 33455";;
  3) WANT="4539962 19900 19855";;
  *) WANT="";;
esac

PASS=0; FAIL=0
ok()  { printf '  \033[32mPASS\033[0m  %s\n' "$1"; PASS=$((PASS+1)); }
bad() { printf '  \033[31mFAIL\033[0m  %s\n' "$1"; FAIL=$((FAIL+1)); }
inv() { docker run --rm -v "$VOL":/staging alpine:3 sh -c "$1" 2>/dev/null; }

echo "Phase 2 verification -- volume $VOL, scale factor $SF"
echo

docker info >/dev/null 2>&1 || { echo "  Docker is not running." >&2; exit 1; }
if ! docker volume inspect "$VOL" >/dev/null 2>&1; then
  echo "  volume '$VOL' does not exist.  Generate it first:"
  echo "    bash scripts/generate-data.sh --scale $SF"
  exit 1
fi

echo "V1/V3  generator report"
REPORT=$(inv "cat $DIR/digen_report.txt")
[ -n "$REPORT" ] && ok "digen_report.txt present" || bad "digen_report.txt missing"
echo "$REPORT" | grep -q "Scale Factor: $SF" && ok "scale factor $SF" || bad "report does not say scale factor $SF"
echo "$REPORT" | grep -q "End Time:" && ok "run finished (End Time written)" \
                                     || bad "no End Time -- generation aborted"
GOT=$(echo "$REPORT" | grep -oE 'Batch[123]: [0-9]+' | grep -oE '[0-9]+$' | tr '\n' ' ')
GOT="${GOT% }"
if [ -n "$WANT" ]; then
  [ "$GOT" = "$WANT" ] && ok "row counts $GOT" || bad "row counts $GOT (expected $WANT)"
else
  N=$(echo "$GOT" | wc -w | tr -d ' ')
  if [ "$N" = 3 ] && ! echo "$GOT" | grep -qE '(^| )0( |$)'; then
    ok "three non-zero batch row counts: $GOT"
    echo "        (no measured baseline for sf$SF -- recorded, not compared)"
  else
    bad "expected three non-zero batch counts, got '$GOT'"
  fi
fi

echo
echo "V2/V8  layout and size"
for B in Batch1 Batch2 Batch3; do
  [ "$(inv "[ -d $DIR/$B ] && echo y")" = y ] && ok "$B present" || bad "$B missing"
done
FW=$(inv "ls $DIR/Batch1 | grep -c '^FINWIRE....Q.$'")
# 203 quarters, 1967Q1-2017Q3: date-driven, so the same at every scale factor
# (confirmed identical at sf3 and sf5).
[ "$FW" = 203 ] && ok "203 FINWIRE files" || bad "FINWIRE files: $FW (expected 203)"
echo "        size on disk: $(inv "du -sh $DIR | cut -f1")"

echo
echo "V4     file inventory (Clauses 2.2.2.1-2.2.2.20)"
MISS=$(inv "
cd $DIR
for f in BatchDate.txt CashTransaction.txt CustomerMgmt.xml DailyMarket.txt \
         Date.txt HR.csv HoldingHistory.txt Industry.txt Prospect.csv \
         StatusType.txt TaxRate.txt Time.txt Trade.txt TradeHistory.txt \
         TradeType.txt WatchHistory.txt; do
  [ -f \"Batch1/\$f\" ] || echo \"Batch1/\$f\"; done
for b in Batch2 Batch3; do
  for f in Account.txt BatchDate.txt CashTransaction.txt Customer.txt \
           DailyMarket.txt HoldingHistory.txt Prospect.csv Trade.txt \
           WatchHistory.txt; do
    [ -f \"\$b/\$f\" ] || echo \"\$b/\$f\"; done; done")
[ -z "$MISS" ] && ok "every expected file present" \
               || bad "missing: $(echo "$MISS" | tr '\n' ' ')"

echo
echo "V5     CDC columns (Clause 1.3.2)"
B1=$(inv "head -1 $DIR/Batch1/Trade.txt | cut -d'|' -f1")
case "$B1" in [IUD]) bad "Batch1 carries a CDC flag ($B1) -- it must not";;
              *)     ok "Batch1 has no CDC flag";; esac
for B in Batch2 Batch3; do
  F=$(inv "head -1 $DIR/$B/Trade.txt | cut -d'|' -f1")
  case "$F" in [IUD]) ok "$B CDC flag present ($F)";;
               *)     bad "$B CDC flag missing (got '$F')";; esac
done

echo
echo "V6     FINWIRE record types at column 16 (Clause 2.2.2.8)"
TYPES=$(inv "cat $DIR/Batch1/FINWIRE????Q? | cut -c16-18 | sort | uniq -c")
echo "$TYPES" | sed 's/^/        /'
N=$(echo "$TYPES" | grep -c .)
[ "$N" = 3 ] && ok "every record classifies as CMP/SEC/FIN" \
             || bad "$N distinct types -- some records do not classify"
# The generator scales FINWIRE linearly: CMP = 0.5 * SF * 1000, SEC = 0.8 * SF
# * 1000.  Confirmed at sf3 (1500/2400) and sf5 (2500/4000).
WANT_CMP=$(( 5 * SF * 100 )); WANT_SEC=$(( 8 * SF * 100 ))
GOT_CMP=$(echo "$TYPES" | awk '$2=="CMP"{print $1}')
GOT_SEC=$(echo "$TYPES" | awk '$2=="SEC"{print $1}')
[ "${GOT_CMP:-0}" = "$WANT_CMP" ] && ok "CMP records $GOT_CMP = 0.5 x SF x 1000" \
                                  || bad "CMP $GOT_CMP (expected $WANT_CMP)"
[ "${GOT_SEC:-0}" = "$WANT_SEC" ] && ok "SEC records $GOT_SEC = 0.8 x SF x 1000" \
                                  || bad "SEC $GOT_SEC (expected $WANT_SEC)"

echo
echo "V7     audit coverage (what tpcdi_audit.sql reads)"
DS=$(inv "cat $DIR/*_audit.csv $DIR/Batch*/*_audit.csv | cut -d, -f1 | sort -u | grep -v DataSet | tr '\n' ' '")
echo "        data sets: $DS"
NDS=$(echo "$DS" | wc -w | tr -d ' ')
[ "$NDS" = 14 ] && ok "14 audit data sets" || bad "$NDS audit data sets (expected 14)"
echo "$DS" | grep -q FactCashBalances \
  && bad "FactCashBalances present -- the audit query expects it absent" \
  || ok "FactCashBalances absent, as the audit query expects"

echo
printf 'passed %d, failed %d\n' "$PASS" "$FAIL"
[ "$FAIL" -eq 0 ] || exit 1
